package db

import (
	"context"
	"time"
)

// Hand-written queries for the client profile page (not SQLC generated).
// These live alongside SQLC output but are not regenerated by it.

// ClientProfileStats holds aggregate purchase stats for one client.
type ClientProfileStats struct {
	TotalSpentCents int64
	ItemsBought     int64
	FirstPurchaseAt *time.Time
}

const clientProfileStats = `
SELECT
    COALESCE((
        SELECT SUM(grand_total)
        FROM branch_invoices
        WHERE client_uid = c.uid AND kind = 'sales'
    ), 0)::bigint,
    COALESCE((
        SELECT SUM(bii.quantity)
        FROM branch_invoice_items bii
        JOIN branch_invoices bi ON bi.id = bii.branch_invoice_id
        WHERE bi.client_uid = c.uid AND bi.kind = 'sales' AND bii.quantity > 0
    ), 0)::bigint,
    (SELECT MIN(occurred_at) FROM branch_invoices WHERE client_uid = c.uid AND kind = 'sales')
FROM clients c
WHERE c.id = $1
`

func (q *Queries) GetClientProfileStats(ctx context.Context, clientID int64) (ClientProfileStats, error) {
	var r ClientProfileStats
	err := q.db.QueryRowContext(ctx, clientProfileStats, clientID).Scan(
		&r.TotalSpentCents, &r.ItemsBought, &r.FirstPurchaseAt,
	)
	return r, err
}

// GetClientHomeBranch returns the name of the branch where the client
// has made the most purchases.
const clientHomeBranch = `
SELECT br.name
FROM branch_invoices bi
JOIN branches br ON br.id = bi.branch_id
WHERE bi.client_uid = (SELECT uid FROM clients WHERE id = $1)
  AND bi.kind = 'sales'
GROUP BY br.id, br.name
ORDER BY COUNT(*) DESC
LIMIT 1
`

func (q *Queries) GetClientHomeBranch(ctx context.Context, clientID int64) (string, error) {
	var name string
	err := q.db.QueryRowContext(ctx, clientHomeBranch, clientID).Scan(&name)
	return name, err
}

// ClientPaymentMixRow is one slice of the payment-mix breakdown.
type ClientPaymentMixRow struct {
	AccountName string
	TotalCents  int64
}

const clientPaymentMix = `
SELECT bip.account_name, SUM(bip.amount)::bigint AS total_cents
FROM branch_invoice_payments bip
JOIN branch_invoices bi ON bi.id = bip.branch_invoice_id
WHERE bi.client_uid = (SELECT uid FROM clients WHERE id = $1)
  AND bi.kind = 'sales'
GROUP BY bip.account_name
ORDER BY total_cents DESC
`

func (q *Queries) ListClientPaymentMix(ctx context.Context, clientID int64) ([]ClientPaymentMixRow, error) {
	rows, err := q.db.QueryContext(ctx, clientPaymentMix, clientID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var result []ClientPaymentMixRow
	for rows.Next() {
		var r ClientPaymentMixRow
		if err := rows.Scan(&r.AccountName, &r.TotalCents); err != nil {
			return nil, err
		}
		result = append(result, r)
	}
	return result, rows.Err()
}

// ClientRecentInvoiceRow is one row in the recent-purchases table.
type ClientRecentInvoiceRow struct {
	ID              int64
	InvoiceCode     string
	GrandTotal      int64
	OccurredAt      time.Time
	BranchName      string
	ItemCount       int64
	PaymentMethods  string // comma-separated
}

const clientRecentInvoices = `
SELECT
    bi.id,
    bi.branch_invoice_code,
    bi.grand_total,
    bi.occurred_at,
    br.name AS branch_name,
    COALESCE((
        SELECT SUM(quantity) FROM branch_invoice_items
        WHERE branch_invoice_id = bi.id AND quantity > 0
    ), 0)::bigint AS item_count,
    COALESCE(STRING_AGG(DISTINCT bip.account_name, ', '), '') AS payment_methods
FROM branch_invoices bi
JOIN branches br ON br.id = bi.branch_id
LEFT JOIN branch_invoice_payments bip ON bip.branch_invoice_id = bi.id
WHERE bi.client_uid = (SELECT uid FROM clients WHERE id = $1)
  AND bi.kind = 'sales'
GROUP BY bi.id, br.name, bi.grand_total, bi.occurred_at, bi.branch_invoice_code
ORDER BY bi.occurred_at DESC
LIMIT 10
`

func (q *Queries) ListClientRecentInvoices(ctx context.Context, clientID int64) ([]ClientRecentInvoiceRow, error) {
	rows, err := q.db.QueryContext(ctx, clientRecentInvoices, clientID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var result []ClientRecentInvoiceRow
	for rows.Next() {
		var r ClientRecentInvoiceRow
		if err := rows.Scan(&r.ID, &r.InvoiceCode, &r.GrandTotal, &r.OccurredAt,
			&r.BranchName, &r.ItemCount, &r.PaymentMethods); err != nil {
			return nil, err
		}
		result = append(result, r)
	}
	return result, rows.Err()
}

// ClientMonthlySpendRow is one month of the spend series.
type ClientMonthlySpendRow struct {
	Month      string // "YYYY-MM"
	TotalCents int64
}

const clientMonthlySpend = `
SELECT
    TO_CHAR(bi.occurred_at, 'YYYY-MM') AS month,
    SUM(bi.grand_total)::bigint AS total_cents
FROM branch_invoices bi
WHERE bi.client_uid = (SELECT uid FROM clients WHERE id = $1)
  AND bi.kind = 'sales'
  AND bi.occurred_at >= NOW() - INTERVAL '12 months'
GROUP BY month
ORDER BY month
`

func (q *Queries) ListClientMonthlySpend(ctx context.Context, clientID int64) ([]ClientMonthlySpendRow, error) {
	rows, err := q.db.QueryContext(ctx, clientMonthlySpend, clientID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var result []ClientMonthlySpendRow
	for rows.Next() {
		var r ClientMonthlySpendRow
		if err := rows.Scan(&r.Month, &r.TotalCents); err != nil {
			return nil, err
		}
		result = append(result, r)
	}
	return result, rows.Err()
}
